    +'Fait le\u00a0: <strong>'+sigDateFr+'</strong>'+(sigLieu?'\u00a0\u00e0\u00a0<strong>'+sigLieu+'</strong>':'')
    +'<br><br>Signature\u00a0:<br>'+sigImg+'</td></tr></table>';

  const pAuto='<div class="page">'+hdr
    +'<h2>AUTORISATION D\u2019INTERVENTION</h2>'
    +'<p>'+dLine+'</p>'
    +'<p>Les sapeurs-pompiers se sont pr\u00e9sent\u00e9s au\u00a0<em>(adresse)</em>\u00a0: <strong>'+adresse+'</strong></p>'
    +'<p>Commune\u00a0<strong>'+commune+'</strong>, \u00e0 la date du\u00a0: <strong>'+dateFr+'</strong></p>'
    +'<p>Pour\u00a0<em>(objet de l\u2019intervention)</em>\u00a0: <strong>'+objet+'</strong></p>'
    +'<p>Lors de cette intervention a \u00e9t\u00e9 r\u00e9alis\u00e9\u00a0<em>(nature de l\u2019intervention)</em>\u00a0: <strong>'+nature+'</strong></p>'
    +'<p><strong>Avant le d\u00e9but de l\u2019intervention</strong>, le '
    +st('propri\u00e9taire',type==='Locataire'||type==='Autre')+', le '
    +st('locataire',type==='Propri\u00e9taire'||type==='Autre')
    +' ou autre a \u00e9t\u00e9 inform\u00e9 express\u00e9ment que la r\u00e9alisation de celle-ci n\u00e9cessite<sup>(1)</sup>\u00a0:</p>'
    +trHtml
    +'<p>'+prop17+'</p>'
    +sigTbl
    +'<p style="font-size:8pt;color:#888;"><sup>(1)</sup> Rayer les mentions inutiles</p>'
    +'</div>';

  const trCochTxt=trCoches.length?'<br>Travaux r\u00e9alis\u00e9s\u00a0: <strong>'+trCoches.join(', ')+'</strong>.':'';
  const pAttest='<div class="page">'+hdr
    +'<h2>ATTESTATION D\u2019INTERVENTION</h2>'
